import { describe, expect, it } from "vitest";
import {
	acceptFamily,
	classifyAgentSurface,
	uaFamily,
} from "@/lib/agent-surface";

describe("classifyAgentSurface", () => {
	it("classifies the prerendered discovery surface middleware is the only observer of", () => {
		expect(classifyAgentSurface("/.well-known/ai-catalog.json")).toBe(
			"well-known",
		);
		expect(classifyAgentSurface("/.well-known/did.json")).toBe("well-known");
		expect(classifyAgentSurface("/.well-known/agent-skills/index.json")).toBe(
			"well-known",
		);
		expect(classifyAgentSurface("/openapi.json")).toBe("openapi");
		expect(classifyAgentSurface("/api/openapi.yaml")).toBe("openapi");
		expect(classifyAgentSurface("/llms.txt")).toBe("llms");
		expect(classifyAgentSurface("/llms-full.txt")).toBe("llms");
		expect(classifyAgentSurface("/docs/llms.txt")).toBe("llms");
	});

	it("groups MCP discovery documents with the MCP transport", () => {
		expect(classifyAgentSurface("/mcp")).toBe("mcp");
		expect(classifyAgentSurface("/api/mcp")).toBe("mcp");
		expect(classifyAgentSurface("/mcp.json")).toBe("mcp");
		expect(classifyAgentSurface("/.well-known/mcp/server-card.json")).toBe(
			"mcp",
		);
		expect(classifyAgentSurface("/.well-known/mcp.json")).toBe("mcp");
	});

	it("classifies the dynamic agent routes", () => {
		expect(classifyAgentSurface("/api/search")).toBe("search");
		expect(classifyAgentSurface("/ask")).toBe("ask");
		expect(classifyAgentSurface("/api/ask")).toBe("ask");
		expect(classifyAgentSurface("/api/md")).toBe("md");
		expect(classifyAgentSurface("/api/md/foundations/overview")).toBe("md");
		expect(classifyAgentSurface("/docs/foundations/overview.md")).toBe("md");
	});

	it("does NOT sweep in internal /api/* routes (no catch-all)", () => {
		// Regression: a `/api/*` catch-all returned "api" for every remaining
		// route, including our own first-party sink. navigator.sendBeacon sends
		// `Accept: */*`, so every search and web-vital beacon minted an extra
		// agent:api-request — roughly doubling ingest volume and filing human
		// traffic under the `agent:` namespace this feature exists to isolate.
		expect(classifyAgentSurface("/api/analytics")).toBeNull();
		expect(classifyAgentSurface("/api/health")).toBeNull();
		expect(classifyAgentSurface("/api/og")).toBeNull();
		// A new agent-facing route must be added to the allowlist on purpose.
	});

	it("returns null for everything that is NOT an agent surface (the volume gate)", () => {
		// Without this, middleware would emit on every page load, RSC payload,
		// static asset and PostHog proxy hit.
		expect(classifyAgentSurface("/")).toBeNull();
		expect(classifyAgentSurface("/docs/foundations/overview")).toBeNull();
		expect(classifyAgentSurface("/pricing")).toBeNull();
		expect(classifyAgentSurface("/ingest/e/")).toBeNull();
		expect(classifyAgentSurface("/_next/data/x.json")).toBeNull();
		expect(classifyAgentSurface("/thumbnails/a.png")).toBeNull();
	});
});

describe("acceptFamily", () => {
	it("labels a real browser Accept as html even though it carries application/*", () => {
		expect(
			acceptFamily(
				"text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
			),
		).toBe("html");
	});

	it("labels agent Accepts", () => {
		expect(acceptFamily("application/json")).toBe("json");
		expect(acceptFamily("application/problem+json")).toBe("json");
		expect(acceptFamily("text/markdown")).toBe("markdown");
		expect(acceptFamily("text/event-stream")).toBe("event-stream");
		expect(acceptFamily("*/*")).toBe("wildcard");
		expect(acceptFamily("")).toBe("none");
		expect(acceptFamily("image/png")).toBe("other");
	});
});

describe("uaFamily", () => {
	it("maps known crawlers and clients onto a bounded set", () => {
		expect(uaFamily("Mozilla/5.0 AppleWebKit (compatible; GPTBot/1.2)")).toBe(
			"gptbot",
		);
		expect(uaFamily("Mozilla/5.0 (compatible; ClaudeBot/1.0)")).toBe(
			"claudebot",
		);
		expect(uaFamily("Mozilla/5.0 (compatible; PerplexityBot/1.0)")).toBe(
			"perplexity",
		);
		expect(uaFamily("curl/8.7.1")).toBe("curl");
		expect(uaFamily("python-httpx/0.27.0")).toBe("python");
		expect(uaFamily("node-fetch/3.3.2")).toBe("node");
		expect(uaFamily("Go-http-client/2.0")).toBe("go");
	});

	it("never leaks a raw user-agent", () => {
		expect(uaFamily("SomeInternalTool/1.0 (contact: ops@example.com)")).toBe(
			"other",
		);
		expect(uaFamily(null)).toBe("none");
		expect(uaFamily("")).toBe("none");
	});

	it("checks crawler tokens before the Mozilla prefix every crawler also sends", () => {
		// A naive "starts with Mozilla → browser" rule would classify GPTBot,
		// ClaudeBot and PerplexityBot as browsers.
		expect(uaFamily("Mozilla/5.0 (Macintosh) Chrome/120 Safari/537.36")).toBe(
			"browser-ua",
		);
	});
});
